package com.siameselang.arp.web;
import com.siameselang.arp.repository.ProgramRepository; import com.siameselang.arp.service.ResourceNotFoundException; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*;
@Controller @RequestMapping("/programs") public class ProgramController {private final ProgramRepository programs;public ProgramController(ProgramRepository programs){this.programs=programs;} @GetMapping String list(Model m){m.addAttribute("programs",programs.findAll());return "programs/list";} @GetMapping("/{id}") String detail(@PathVariable long id,Model m){m.addAttribute("program",programs.findById(id).orElseThrow(()->new ResourceNotFoundException("Program not found")));return "programs/detail";}}
